mapper.select:
SELECT d.id,d.declaration_id AS declarationId,d.revision_no AS revision,d.execution_code AS executionCode,
  d.affected_node_id AS routingNodeId,d.defect_qty AS defectQty,d.record_action AS recordAction,
  n.operation_id AS operationId,d.defect_type_id AS defectTypeId,
  d.defect_type_name_snapshot AS typeName,d.waste_category AS wasteCategory
FROM mes_production_defect d LEFT JOIN routing_node n ON n.id=d.affected_node_id
WHERE NOT EXISTS (SELECT 1 FROM mes_production_defect newer
  WHERE newer.declaration_id=d.declaration_id AND newer.revision_no>d.revision_no)
AND d.execution_code=#{query.executionCode}
AND n.operation_id=#{query.operationId}
AND d.defect_type_id=#{query.defectTypeId}
AND d.waste_category=#{query.wasteCategory}
AND d.occurred_at>=#{query.from}
AND d.occurred_at<=#{query.to}
ORDER BY n.operation_id,d.defect_type_id,d.waste_category,CAST(d.defect_type_name_snapshot AS BINARY(1024)),d.id
LIMIT #{limit} OFFSET #{offset}
